command:
sudo tee /etc/nginx/sites-available/rotating-tls >/dev/null <<'EOF'
server {
    listen 8443 ssl default_server;
    listen [::]:8443 ssl default_server;
    server_name node1.local _;

    ssl_certificate     /etc/ssl/rotating/tls.crt;
    ssl_certificate_key /etc/ssl/rotating/tls.key;

    location / {
        default_type text/plain;
        return 200 "ok\n";
    }
}
EOF
sudo rm -f /etc/nginx/sites-enabled/default
sudo ln -sf /etc/nginx/sites-available/rotating-tls /etc/nginx/sites-enabled/rotating-tls
sudo nginx -t && sudo systemctl enable --now nginx && sudo systemctl reload nginx
systemctl is-active nginx

